#include <zephyr/sys/notify.h>

int sys_notify_validate(struct sys_notify *notify)
{
	int rv = -EINVAL;

	if (notify == NULL) {
		return rv;
	}

	switch (sys_notify_get_method(notify)) {
	case SYS_NOTIFY_METHOD_SPINWAIT:
		rv = 0;
		break;
	case SYS_NOTIFY_METHOD_CALLBACK:
		if (notify->method.callback != NULL) {
			rv = 0;
		}
		break;
#ifdef CONFIG_POLL
	case SYS_NOTIFY_METHOD_SIGNAL:
		if (notify->method.signal != NULL) {
			rv = 0;
		}
		break;
#endif /* CONFIG_POLL */
	default:
		break;
	}

	return rv;
}

sys_notify_generic_callback sys_notify_finalize(struct sys_notify *notify,
						int res)
{
	sys_notify_generic_callback rv = NULL;

	__ASSERT_NO_MSG(notify != NULL);

	notify->result = res;

	switch (sys_notify_get_method(notify)) {
	case SYS_NOTIFY_METHOD_SPINWAIT:
		break;
	case SYS_NOTIFY_METHOD_CALLBACK:
		rv = notify->method.callback;
		__ASSERT_NO_MSG(rv != NULL);
		break;
#ifdef CONFIG_POLL
	case SYS_NOTIFY_METHOD_SIGNAL:
		__ASSERT_NO_MSG(notify->method.signal != NULL);
		k_poll_signal_raise(notify->method.signal, res);
		break;
#endif /* CONFIG_POLL */
	default:
		__ASSERT_NO_MSG(false);
	}

	compiler_barrier();
	notify->flags = SYS_NOTIFY_METHOD_COMPLETED;

	return rv;
}

int z_orig_sys_notify_validate(struct sys_notify *notify);
sys_notify_generic_callback z_orig_sys_notify_finalize(struct sys_notify *notify,
						       int res);
#define sys_notify_validate z_orig_sys_notify_validate
